"""What Kubernetes does for you: a toy control loop.

Generates a Deployment manifest, then simulates the scheduler (place pods on the
least-loaded node with capacity) and the ReplicaSet controller (reconcile actual
pods to the desired replica count) through a pod crash, a node failure and a
scale-up, the way kubelet + controller manager keep the cluster at desired state.
"""
import json

def deployment(name, image, replicas, port=8000):
    return {"apiVersion": "apps/v1", "kind": "Deployment", "metadata": {"name": name},
            "spec": {"replicas": replicas, "selector": {"matchLabels": {"app": name}},
                     "template": {"metadata": {"labels": {"app": name}},
                                  "spec": {"containers": [{"name": name, "image": image,
                                           "ports": [{"containerPort": port}],
                                           "resources": {"requests": {"cpu": "500m"}}}]}}}}

def to_yaml(o, ind=0):
    pad = "  " * ind; out = []
    for k, v in o.items():
        if isinstance(v, dict): out.append(f"{pad}{k}:"); out.append(to_yaml(v, ind + 1))
        elif isinstance(v, list):
            out.append(f"{pad}{k}:")
            for item in v:
                sub = to_yaml(item, ind + 2).splitlines(); out.append(f"{pad}  - {sub[0].strip()}"); out += sub[1:]
        else: out.append(f"{pad}{k}: {v}")
    return "\n".join(out)

dep = deployment("iris-model", "iris-model:1.0", replicas=3)
print(to_yaml(dep)); print("kubectl apply -f deployment.yaml\n")

nodes = {"node-a": {"cap": 4, "up": True}, "node-b": {"cap": 4, "up": True}, "node-c": {"cap": 2, "up": True}}
pods, counter = {}, 0
def load(n): return sum(1 for p in pods.values() if p == n)

def schedule():
    ok = [n for n, s in nodes.items() if s["up"] and load(n) < s["cap"]]
    return min(ok, key=lambda n: load(n) / nodes[n]["cap"]) if ok else None

def reconcile(desired, why):
    global counter
    for p in [p for p, n in pods.items() if not nodes[n]["up"]]: del pods[p]   # pods on dead nodes are gone
    while len(pods) < desired:
        n = schedule(); counter += 1
        if n is None: print("   no capacity: pod Pending"); break
        pods[f"pod-{counter}"] = n
    while len(pods) > desired: pods.pop(sorted(pods)[-1])
    print(f"{why:<34} desired={desired} running={len(pods)} " + json.dumps({n: load(n) for n in nodes if nodes[n]['up']}))

reconcile(3, "initial rollout")
del pods["pod-2"];               reconcile(3, "pod-2 crashed -> replaced")
nodes["node-a"]["up"] = False;   reconcile(3, "node-a failed -> rescheduled")
reconcile(6, "scale up to 6 replicas")
reconcile(8, "scale to 8: cluster full")
